import os
import torch


class Config:
    # ==========================================
    # 1. Paths & Directories
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"
    SUBMISSION_DIR = "./submission"

    # Unique identifier for this solution iteration
    IDEA_ID = "idea_33"

    # Cache directory for deterministic data processing
    # We use this to store intermediate parquet/npy files
    CACHE_DIR = os.path.join(WORKING_DIR, IDEA_ID)

    # Input Metadata Files (Generated by metadata script)
    TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Submission File
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # 2. General Settings
    # ==========================================
    RANDOM_SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # Number of workers for data loading
    NUM_WORKERS = 2

    # Debugging: Set to a small integer (e.g., 100) to limit dataset size for quick testing
    # Set to None for full run
    DEBUG_SAMPLE_SIZE = None

    # ==========================================
    # 3. Feature Engineering Configuration
    # ==========================================
    # Text Embeddings (SBERT)
    SBERT_MODEL_NAME = "all-MiniLM-L6-v2"
    SBERT_BATCH_SIZE = 32

    # TF-IDF Settings (Stream A - Random Forest)
    TFIDF_MAX_FEATURES = 5000
    TFIDF_NGRAM_RANGE = (1, 2)

    # Subreddit Analysis Settings
    # Number of top subreddits to select based on Mutual Information
    TOP_K_SUBREDDIT_INDICATORS = 50

    # ==========================================
    # 4. Model: Random Forest (Stream A)
    # ==========================================
    # Hyperparameters based on "Predictive-Relevance" strategy
    RF_N_ESTIMATORS = 500
    RF_MIN_SAMPLES_LEAF = 1
    RF_CLASS_WEIGHT = "balanced"
    RF_N_JOBS = -1  # Use all available cores

    # ==========================================
    # 5. Model: MLP (Stream B)
    # ==========================================
    # Architecture Dimensions
    MLP_INPUT_EMBEDDING_DIM = 384  # Output dimension of all-MiniLM-L6-v2
    MLP_HIDDEN_DIM = 256

    # Regularization (Dropout-Only Regime)
    MLP_EMBEDDING_DROPOUT = 0.5
    MLP_DENSE_DROPOUT = 0.2

    # Training Hyperparameters
    MLP_BATCH_SIZE = 32
    MLP_LEARNING_RATE = 1e-4
    MLP_WEIGHT_DECAY = 1e-2
    MLP_MAX_EPOCHS = 50
    MLP_PATIENCE = 15  # Early stopping patience

    # ==========================================
    # 6. Ensemble Configuration
    # ==========================================
    # Simple Weighted Average
    WEIGHT_RF = 0.5
    WEIGHT_MLP = 0.5

    @classmethod
    def setup(cls):
        """
        Creates necessary working directories for cache and submission.
        Should be called at the start of the pipeline.
        """
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Print configuration summary
        print(f"Configuration Loaded for {cls.IDEA_ID}")
        print(f"Device: {cls.DEVICE}")
        print(f"Cache Directory: {cls.CACHE_DIR}")
        print(f"Random Seed: {cls.RANDOM_SEED}")
